const guardrail = new CfnGuardrail(this, 'IntakeGuardrail', {
  name: 'clinical-intake',
  contentPolicyConfig: { filtersConfig: [ { type: 'VIOLENCE', inputStrength: 'HIGH', outputStrength: 'HIGH' } ] },
  topicPolicyConfig: { topicsConfig: [ { name: 'non-clinical-advice', type: 'DENY', definition: 'advice outside the clinical scope' } ] },
  wordPolicyConfig: { wordsConfig: [ { text: 'competitor-name' } ] },
});

